func TestMigrateOSS(t *testing.T) {
	ctx := context.Background()

	t.Run("EmptyCluster", func(t *testing.T) {
		as := newTestAuthServer(t)
		clock := clockwork.NewFakeClock()
		as.SetClock(clock)

		err := migrateOSS(ctx, as)
		require.NoError(t, err)

